import{_ as e,o as t,c as o,ak as a}from"./chunks/framework.CwlS7rl1.js";const u=JSON.parse('{"title":"包与依赖关系","description":"","frontmatter":{},"headers":[],"relativePath":"npm-package-dependency.md","filePath":"npm-package-dependency.md","lastUpdated":1786395082000}'),c={name:"npm-package-dependency.md"};function n(s,d,i,r,l,p){return t(),o("div",null,[...d[0]||(d[0]=[a(`<h1 id="包与依赖关系" tabindex="-1">包与依赖关系 <a class="header-anchor" href="#包与依赖关系" aria-label="Permalink to &quot;包与依赖关系&quot;">​</a></h1><p>XiHan.UI 是一个 pnpm workspace。<code>packages/*</code> 是对外发布的库包，<code>tooling/*</code> 是内部工具（永不发布），<code>apps/*</code> 是两个 playground。</p><h2 id="全部库包" tabindex="-1">全部库包 <a class="header-anchor" href="#全部库包" aria-label="Permalink to &quot;全部库包&quot;">​</a></h2><table tabindex="0"><thead><tr><th>包</th><th>版本</th><th>依赖</th><th>peer 依赖</th><th>层</th></tr></thead><tbody><tr><td><code>@xihan-ui/kernel</code></td><td><code>0.0.0</code></td><td>—</td><td>—</td><td>1</td></tr><tr><td><code>@xihan-ui/machine</code></td><td><code>0.0.0</code></td><td><code>core</code></td><td>—</td><td>1</td></tr><tr><td><code>@xihan-ui/tokens</code></td><td><code>0.0.0</code></td><td>—</td><td>—</td><td>1</td></tr><tr><td><code>@xihan-ui/icons</code></td><td><code>0.9.8</code></td><td>—</td><td>—</td><td>1</td></tr><tr><td><code>@xihan-ui/behavior</code></td><td><code>0.0.0</code></td><td><code>core</code></td><td>—</td><td>2</td></tr><tr><td><code>@xihan-ui/position</code></td><td><code>0.0.0</code></td><td><code>core</code></td><td>—</td><td>2</td></tr><tr><td><code>@xihan-ui/code-highlight</code></td><td><code>0.0.0</code></td><td><code>core</code></td><td>—</td><td>2</td></tr><tr><td><code>@xihan-ui/chat-stream</code></td><td><code>0.0.0</code></td><td><code>core</code></td><td>—</td><td>2</td></tr><tr><td><code>@xihan-ui/markdown</code></td><td><code>0.0.0</code></td><td>—</td><td>—</td><td>2</td></tr><tr><td><code>@xihan-ui/headless</code></td><td><code>0.0.0</code></td><td><code>core</code> <code>machine</code> <code>behavior</code> + <code>@internationalized/date</code></td><td>—</td><td>3</td></tr><tr><td><code>@xihan-ui/styles</code></td><td><code>0.0.0</code></td><td><code>system</code>（只取其 CSS 产物）</td><td>—</td><td>3</td></tr><tr><td><code>@xihan-ui/backgrounds</code></td><td><code>0.0.0</code></td><td><code>core</code> <code>behavior</code></td><td>—</td><td>3</td></tr><tr><td><code>@xihan-ui/vue</code></td><td><code>0.0.0</code></td><td><code>core</code> <code>machine</code> <code>behavior</code> <code>headless</code> <code>position</code> <code>highlight</code></td><td><code>vue</code>、<code>visual</code>（可选）</td><td>4</td></tr><tr><td><code>@xihan-ui/web-components</code></td><td><code>0.0.0</code></td><td><code>core</code> <code>machine</code> <code>behavior</code> <code>headless</code> <code>position</code> <code>highlight</code></td><td><code>visual</code>（可选）</td><td>4</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">版本状态</p><p>除 <code>@xihan-ui/icons</code> 外全部是 <code>0.0.0</code>——<strong>尚未发布到 npm</strong>。<code>icons</code> 是一个冻结的遗留包：不进构建图、不发布，源码里还引着已经删掉的依赖，在它重建之前不要使用。</p><p>发布走 changesets，所有库包同属一个 fixed 版本组，届时会一起升到同一个版本号。</p></div><h2 id="依赖图" tabindex="-1">依赖图 <a class="header-anchor" href="#依赖图" aria-label="Permalink to &quot;依赖图&quot;">​</a></h2><p>箭头方向 = 依赖方向，只画实际声明的依赖。同层之间除 <code>machine → core</code> 外无横向依赖。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>层 4   ┌─────────────┐          ┌─────────────┐</span></span>
<span class="line"><span>       │     vue     │          │     wc      │   peer: visual（可选）；vue 另有 peer: vue</span></span>
<span class="line"><span>       └──────┬──────┘          └──────┬──────┘</span></span>
<span class="line"><span>              │  core · machine · behavior · headless · position · highlight</span></span>
<span class="line"><span>              └────────────┬───────────┘</span></span>
<span class="line"><span>                           ▼</span></span>
<span class="line"><span>层 3   ┌──────────────┐  ┌──────────┐        ┌────────────────┐</span></span>
<span class="line"><span>       │   headless   │  │  visual  │        │ styled（纯CSS）│</span></span>
<span class="line"><span>       └──────┬───────┘  └────┬─────┘        └───────┬────────┘</span></span>
<span class="line"><span>   core·machine·behavior   core·behavior         system 的 CSS 产物</span></span>
<span class="line"><span>        + @internationalized/date</span></span>
<span class="line"><span>              │               │</span></span>
<span class="line"><span>              ▼               ▼</span></span>
<span class="line"><span>层 2   ┌──────────┐ ┌──────────┐ ┌───────────┐ ┌──────┐ ┌──────────┐</span></span>
<span class="line"><span>       │ behavior │ │ position │ │ highlight │ │  ai  │ │ markdown │</span></span>
<span class="line"><span>       └────┬─────┘ └────┬─────┘ └─────┬─────┘ └──┬───┘ └──────────┘</span></span>
<span class="line"><span>            └────────────┴─────────────┴──────────┘         无依赖</span></span>
<span class="line"><span>                           ▼</span></span>
<span class="line"><span>层 1   ┌──────────┐  ┌──────────┐   ┌──────────┐  ┌───────┐</span></span>
<span class="line"><span>       │   core   │◄─┤ machine  │   │  system  │  │ icons │</span></span>
<span class="line"><span>       └──────────┘  └──────────┘   └──────────┘  └───────┘</span></span>
<span class="line"><span>        零运行时依赖   零运行时依赖      无依赖        冻结</span></span></code></pre></div><p>三个包完全独立、可以单独用：</p><ul><li><strong><code>@xihan-ui/tokens</code></strong>——只要设计令牌与主题运行时，不要组件；</li><li><strong><code>@xihan-ui/markdown</code></strong>——只要流式 Markdown 渲染内核；</li><li><strong><code>@xihan-ui/styles</code></strong>——纯 CSS，它对 <code>system</code> 的依赖只是为了 <code>@import</code> 令牌产物，不引入任何 JS。</li></ul><h2 id="依赖规则" tabindex="-1">依赖规则 <a class="header-anchor" href="#依赖规则" aria-label="Permalink to &quot;依赖规则&quot;">​</a></h2><p>分层拓扑写在 <code>tooling/eslint-config/src/layers.json</code> 里，由 dependency-cruiser 在 <code>pnpm boundaries</code> 时强制。层级越低越基础，只能依赖 <code>canDependOn</code> 列出的包。</p><p>除分层外还有四条规则：</p><table tabindex="0"><thead><tr><th>规则</th><th>内容</th></tr></thead><tbody><tr><td><code>no-circular</code></td><td>禁止循环依赖</td></tr><tr><td><code>no-unresolvable</code></td><td>解析不出来的 import——最常见的成因正是「伸手够了邻层却没在 <code>package.json</code> 里声明依赖」</td></tr><tr><td><code>styled-no-js-deps</code></td><td><code>styled</code> 是纯 CSS，不得依赖任何 JS 包</td></tr><tr><td><code>no-external-in-packages</code></td><td>库包的运行时代码不得引第三方</td></tr></tbody></table><p><code>icons</code> 因为是冻结的遗留包，暂时豁免 <code>no-unresolvable</code>。</p><h2 id="第三方运行时依赖" tabindex="-1">第三方运行时依赖 <a class="header-anchor" href="#第三方运行时依赖" aria-label="Permalink to &quot;第三方运行时依赖&quot;">​</a></h2><p><strong>全库只有一个</strong>：<code>@internationalized/date</code>，只在 <code>@xihan-ui/headless</code> 的日期族里用（零框架的纯数据包，无副作用）。</p><p>以下东西都是自研的，不引第三方：</p><table tabindex="0"><thead><tr><th>能力</th><th>包</th><th>常见的第三方选择</th></tr></thead><tbody><tr><td>浮层定位</td><td><code>position</code></td><td>Floating UI</td></tr><tr><td>代码着色</td><td><code>highlight</code></td><td>Shiki / Prism</td></tr><tr><td>Web Components 响应式基类</td><td><code>wc</code></td><td>Lit</td></tr><tr><td>Markdown 渲染</td><td><code>markdown</code></td><td>markdown-it / marked</td></tr><tr><td>状态机</td><td><code>machine</code></td><td>XState</td></tr></tbody></table><p>要新增第三方运行时依赖，必须逐条登记进白名单并写明理由与摘除条件，<code>check-runtime-deps</code> 门禁盯着这件事。</p><div class="tip custom-block"><p class="custom-block-title">开发期第三方是另一回事</p><p><code>@lit/reactive-element</code> 与 <code>commonmark-spec</code> 出现在 workspace catalog 里，但它们只供测试对拍——前者用于差分校验自研响应式基类，后者用于读 CommonMark 官方用例。两者都不进任何包的运行时依赖。</p></div><h2 id="版本约定" tabindex="-1">版本约定 <a class="header-anchor" href="#版本约定" aria-label="Permalink to &quot;版本约定&quot;">​</a></h2><ul><li>内部依赖一律 <code>workspace:*</code>；</li><li>第三方版本只从 workspace catalog 取，包内写 <code>catalog:</code>，<strong>不得内联版本号</strong>（<code>check-exact-pins</code> 门禁）；</li><li>升级只改 <code>pnpm-workspace.yaml</code> 的 catalog 一处。</li></ul><h2 id="产物契约" tabindex="-1">产物契约 <a class="header-anchor" href="#产物契约" aria-label="Permalink to &quot;产物契约&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>模块格式</td><td>ESM only，不提供 CJS</td></tr><tr><td>Node</td><td><code>&gt;= 24</code></td></tr><tr><td>类型</td><td>每个入口一份 <code>.d.ts</code></td></tr><tr><td>副作用</td><td>全部 <code>sideEffects: false</code>，<code>styled</code> 与 <code>system/tokens.css</code> 除外</td></tr></tbody></table><p><code>pnpm gate:publish</code> 逐包跑 publint 与 attw，按 ESM-only 的支持面校验 exports 条件与类型解析（<code>node16-from-ESM</code> 与 <code>bundler</code> 两列）。</p><h2 id="子路径导出" tabindex="-1">子路径导出 <a class="header-anchor" href="#子路径导出" aria-label="Permalink to &quot;子路径导出&quot;">​</a></h2><p>大多数包只有主入口。有子路径的：</p><table tabindex="0"><thead><tr><th>包</th><th>子路径</th></tr></thead><tbody><tr><td><code>@xihan-ui/tokens</code></td><td><code>./runtime</code> <code>./tokens.css</code> <code>./tokens.json</code></td></tr><tr><td><code>@xihan-ui/machine</code></td><td><code>./vanilla</code></td></tr><tr><td><code>@xihan-ui/behavior</code></td><td><code>./presence</code></td></tr><tr><td><code>@xihan-ui/vue</code></td><td><code>./visual</code></td></tr><tr><td><code>@xihan-ui/web-components</code></td><td><code>./define</code> <code>./visual</code> <code>./custom-elements.json</code></td></tr><tr><td><code>@xihan-ui/styles</code></td><td>每个组件一份 CSS，共 74 条</td></tr></tbody></table><p>组件<strong>没有</strong>单独的子路径导出——按需引入靠 tree-shaking，不靠手写路径。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="./overview#分层与依赖矩阵">架构总览</a></li><li><a href="./installation">安装与接入</a></li><li><a href="./guide/testing#结构门禁">测试与质量门禁</a></li></ul>`,32)])])}const m=e(c,[["render",n]]);export{u as __pageData,m as default};
